static uint8_t param_scope(param_id_t id,persist_param_scope_t*out){if(out==NULL)return 0U;const track_runtime_param_rule_t rule=track_runtime_get_param_rule(id);if(rule.domain==TRACK_RUNTIME_PARAM_DOMAIN_GLOBAL&&rule.status==TRACK_RUNTIME_PARAM_GLOBAL_ALLOWED){*out=PERSIST_PARAM_SCOPE_GLOBAL;return 1U;}if(rule.domain!=TRACK_RUNTIME_PARAM_DOMAIN_NONE&&rule.domain!=TRACK_RUNTIME_PARAM_DOMAIN_GLOBAL&&rule.status==TRACK_RUNTIME_PARAM_ALLOWED){*out=PERSIST_PARAM_SCOPE_ENTITY;return 1U;}return 0U;}
static persist_control_value_kind_t param_kind(param_id_t id){(void)id;return PERSIST_VALUE_FLOAT32;}
uint8_t persist_key_param_descriptor(param_id_t id,persist_param_descriptor_t *out)
{
    if(out==NULL||id>=PARAM_COUNT||param_id_is_reserved(id))return 0U;
    if(g_param_keys[id]==0U)return 0U;
    out->key=g_param_keys[id];
    out->kind=param_kind(id);
    if(param_scope(id,&out->scope)==0U)return 0U;
    out->plockable=seq_param_iface_is_param_plockable(id);
    return 1U;
}
uint8_t persist_key_param_to_disk(param_id_t id,persist_control_parameter_key_t *out){persist_param_descriptor_t d;if(out==NULL||persist_key_param_descriptor(id,&d)==0U||d.key==0U)return 0U;*out=d.key;return 1U;}
uint8_t persist_key_param_from_disk(persist_control_parameter_key_t key,param_id_t *out){if(out==NULL||key==0U)return 0U;for(param_id_t id=0U;id<PARAM_COUNT;++id)if(!param_id_is_reserved(id)&&g_param_keys[id]==key){*out=id;return 1U;}return 0U;}
