static const uint32_t lfo_shapes[]={PERSIST_LFO_SHAPE_SINE,PERSIST_LFO_SHAPE_TRIANGLE,PERSIST_LFO_SHAPE_SAW,PERSIST_LFO_SHAPE_SQUARE,PERSIST_LFO_SHAPE_RANDOM_SH,PERSIST_LFO_SHAPE_SINE_POS,PERSIST_LFO_SHAPE_TRIANGLE_POS,PERSIST_LFO_SHAPE_SQUARE_POS,PERSIST_LFO_SHAPE_REVERSE_SAW};
uint8_t persist_key_lfo_shape_to_disk(mod_lfo_shape_t v,uint32_t*out){if(out==NULL||(uint8_t)v>=MOD_LFO_SHAPE_COUNT)return 0U;*out=lfo_shapes[v];return 1U;}uint8_t persist_key_lfo_shape_from_disk(uint32_t k,mod_lfo_shape_t*out){if(out==NULL)return 0U;for(uint8_t i=0U;i<MOD_LFO_SHAPE_COUNT;++i)if(lfo_shapes[i]==k){*out=(mod_lfo_shape_t)i;return 1U;}return 0U;}
